# Build the pinned Windows project generated by build-libvpx.sh windows-project.
# No installation, certificate trust, elevation or host policy changes.
[CmdletBinding()]
param(
    [Parameter(Mandatory)][string]$Root,
    [Parameter(Mandatory)][string]$NasmDirectory
)
$ErrorActionPreference='Stop'
$nativeRoot=[IO.Path]::GetFullPath($Root)
$source=Join-Path $nativeRoot 'source'
$build=Join-Path $nativeRoot 'build'
if((git -C $source rev-parse HEAD) -ne '1024874c5919305883187e2953de8fcb4c3d7fa6'){throw 'libvpx revision mismatch'}
if(-not (Test-Path -LiteralPath (Join-Path $build 'vpx.sln') -PathType Leaf)){throw 'Generate the pinned Windows project first with build-libvpx.sh windows-project'}
if(-not (Test-Path -LiteralPath (Join-Path $NasmDirectory 'nasm.exe') -PathType Leaf)){throw 'The verified NASM executable is missing'}
$vswhere=Join-Path ${env:ProgramFiles(x86)} 'Microsoft Visual Studio\Installer\vswhere.exe'
$installation=& $vswhere -latest -products '*' -requires Microsoft.Component.MSBuild -property installationPath
if(-not $installation){throw 'MSBuild is required'}
$msbuild=Join-Path $installation 'MSBuild\Current\Bin\MSBuild.exe'
$sdkRoot=(Get-ItemProperty -LiteralPath 'HKLM:\SOFTWARE\Microsoft\Windows Kits\Installed Roots').KitsRoot10
$sdkVersion=(Get-ChildItem -LiteralPath (Join-Path $sdkRoot 'Lib') -Directory | Where-Object {Test-Path -LiteralPath (Join-Path $_.FullName 'um\x64\kernel32.lib')} | Sort-Object {[version]$_.Name} -Descending | Select-Object -First 1).Name
if(-not $sdkVersion){throw 'An x64 Windows SDK is required'}
$env:PATH=$NasmDirectory+';'+$env:PATH
# Rust repacks static native archives. MSVC /GL objects lose their proprietary
# symbol index during that operation, so supply ordinary optimized COFF objects.
& $msbuild (Join-Path $build 'vpx.sln') /p:Configuration=Release /p:Platform=x64 "/p:WindowsTargetPlatformVersion=$sdkVersion" /p:WholeProgramOptimization=false /m:2 /v:minimal /nologo
if($LASTEXITCODE -ne 0){exit $LASTEXITCODE}
$env:VPX_INCLUDE_DIR=$source
$env:VPX_LIB_DIR=Join-Path $build 'x64\Release'
$env:VPX_LIB_NAME='vpxmd'
if($env:GITHUB_ENV){
    "VPX_INCLUDE_DIR=$env:VPX_INCLUDE_DIR" | Out-File -FilePath $env:GITHUB_ENV -Encoding utf8 -Append
    "VPX_LIB_DIR=$env:VPX_LIB_DIR" | Out-File -FilePath $env:GITHUB_ENV -Encoding utf8 -Append
    'VPX_LIB_NAME=vpxmd' | Out-File -FilePath $env:GITHUB_ENV -Encoding utf8 -Append
}
Write-Output "Built pinned VP8 library: $env:VPX_LIB_DIR"
